package org.sleepwell.app;
/** One private current-occurrence response; no camera image, identity or body template. */
final class PoseProof {final String run,nonce;final int unit;final long issued;private boolean consumed;PoseProof(String run,int unit,String nonce,long issued){if(run==null||run.isBlank()||run.length()>128||unit<0||nonce==null||!java.util.UUID.fromString(nonce).toString().equals(nonce)||issued<0)throw new IllegalArgumentException("Invalid pose request");this.run=run;this.unit=unit;this.nonce=nonce;this.issued=issued;}boolean consume(String responseRun,int responseUnit,String responseNonce,long captured,long now,String currentRun,int currentUnit,boolean taskCurrent,boolean fallback){if(consumed)return false;if(!taskCurrent||!run.equals(currentRun)||unit!=currentUnit){consumed=true;return false;}if(!run.equals(responseRun)||unit!=responseUnit||!nonce.equals(responseNonce)||!fallback&&(captured<issued||captured>now||now-captured>10000))return false;consumed=true;return true;}}
